const ids = ["G01","G02","G03","G04","G05","G06"];
const packets = await Promise.all(ids.map(id=>tools.origin_packet({case_id:id})));
for (const p of packets){
  const c=p.cases[0], e=c.evidence;
  const mats=new Map(e.material_index.map(m=>[m.id,m]));
  const parents=new Map();
  for(const l of e.links){ if(l.relation==="derivation"){ if(!parents.has(l.child)) parents.set(l.child,[]); parents.get(l.child).push(l.parent);} }
  const memo=new Map(), visiting=new Set();
  function origins(id){
    if(memo.has(id)) return memo.get(id);
    const ps=parents.get(id)||[];
    let out;
    if(ps.length===0){ out=new Set([mats.get(id).source_id]); }
    else { out=new Set(); for(const q of ps) for(const s of origins(q)) out.add(s); }
    memo.set(id,out); return out;
  }
  const all=new Set();
  for(const m of e.material_index) for(const s of origins(m.id)) all.add(s);
  console.log(c.id, "computedAll", all.size, [...all].sort().join(","), "| recorded", e.recorded_origin_count, JSON.stringify(e.recorded_origins), "| match", all.size===e.recorded_origin_count);
  console.log("  queries", c.query_ids.map(q=>q+":"+[...origins(q)].sort().join(",")).join(" | "));
}
